// Un JWT a trois parties separees par des points : en-tete.charge-utile.signature
// Voici la charge utile (payload) d'un ID Token une fois decodee en JSON :
{
  "iss": "https://auth.exemple.fr",   // emetteur : le serveur d'autorisation
  "sub": "248289761001",              // identifiant stable de l'utilisateur
  "aud": "client-web-skillforge",     // destinataire : notre client
  "exp": 1735689600,                   // expiration (timestamp Unix)
  "iat": 1735686000,                   // date d'emission
  "email": "alice@exemple.fr",
  "name": "Alice Martin"
}

// Cote client, on NE fait confiance a ces claims QU'APRES avoir :
//  1. verifie la signature cryptographique du jeton,
//  2. verifie que "aud" correspond bien a notre identifiant de client,
//  3. verifie que "exp" n'est pas depasse.
